export function debounce<Args extends unknown[], R>(
  fn: (...args: Args) => R,
  delayMs: number,
): (...args: Args) => R | undefined {
  let timerId: ReturnType<typeof setTimeout> | null = null;
  let lastResult: R | undefined;

  return (...args: Args): R | undefined => {
    if (timerId !== null) {
      clearTimeout(timerId);
    }
    timerId = setTimeout(() => {
      timerId = null;
      lastResult = fn(...args);
    }, delayMs);

    return lastResult;
  };
}
